// Pull the sync state saved by the previous run (ETag + watermark) out of
// workflow static data, and carry the config forward on the same item.
const store = $getWorkflowStaticData('global');
const cfg = $('Set Config').first().json;
const state = {
  repoOwner: cfg.repoOwner,
  repoName: cfg.repoName,
  minFollowers: cfg.minFollowers,
  minPublicRepos: cfg.minPublicRepos,
  minRateRemaining: cfg.minRateRemaining,
  openAiModel: cfg.openAiModel || 'gpt-4o-mini',
  stargazersEtag: store.stargazersEtag || '',
  lastStarredAt: store.lastStarredAt || ''
};
console.log('[lead-sniper] poll start repo=' + state.repoOwner + '/' + state.repoName +
  ' etag=' + (state.stargazersEtag ? 'set' : 'none') +
  ' watermark=' + (state.lastStarredAt || 'none (baseline run)'));
return [{ json: state }];

// GitHub returns stargazers oldest-first, so new stars are on the LAST page.
// Read the page count from the RFC-5988 Link header instead of paginating.
// Also surface the primary rate-limit budget for the guard below.
const res = $input.first().json;
const headers = res.headers || {};
const link = headers.link || headers.Link || '';
const m = link.match(/[?&]page=(\d+)>;\s*rel="last"/);
const remaining = parseInt(headers['x-ratelimit-remaining'] ?? '9999', 10);
const lastPage = m ? parseInt(m[1], 10) : 1;
console.log('[lead-sniper] discovery: lastPage=' + lastPage + ' rateRemaining=' + remaining);
return [{ json: { lastPage, rateRemaining: remaining } }];

// Handle the conditional response from the stargazer poll.
const store = $getWorkflowStaticData('global');
const res = $input.first().json;
const status = res.statusCode || 200;
const headers = res.headers || {};

// 304 Not Modified: nothing starred since last poll. This response does not
// consume the primary REST rate limit. End the cycle.
if (status === 304) {
  console.log('[lead-sniper] 304 Not Modified: no new stars, ending cycle');
  return [];
}

// Rate limited (secondary/abuse or primary exhausted mid-cycle): log the reset
// hint and end the cycle. The next scheduled run retries; we deliberately do
// not block this execution on a long Wait.
if (status === 403 || status === 429) {
  console.log('[lead-sniper] ' + status + ' rate limited. retry-after=' +
    (headers['retry-after'] || 'n/a') + ' x-ratelimit-reset=' +
    (headers['x-ratelimit-reset'] || 'n/a') + '. Skipping this cycle.');
  return [];
}

if (status >= 400) {
  console.log('[lead-sniper] unexpected status ' + status + ' from stargazer poll, ending cycle');
  return [];
}

// Save the new ETag for next run's conditional request.
const newEtag = headers.etag || headers.ETag;
if (newEtag) store.stargazersEtag = newEtag;

const body = Array.isArray(res.body) ? res.body : [];
const prev = store.lastStarredAt ? new Date(store.lastStarredAt) : null;

// Advance the watermark to the newest star we can see this poll.
let newest = prev || new Date(0);
for (const it of body) {
  const t = new Date(it.starred_at);
  if (t > newest) newest = t;
}
store.lastStarredAt = newest.toISOString();

// First run has no watermark: record the baseline and emit nothing. Genuinely
// new stars are picked up on the next poll. No back-seeding of existing stars.
if (!prev) {
  console.log('[lead-sniper] baseline run: recorded watermark ' + store.lastStarredAt + ', emitting 0');
  return [];
}

const fresh = body.filter((it) => new Date(it.starred_at) > prev);
console.log('[lead-sniper] ' + fresh.length + ' new stargazer(s) since ' + prev.toISOString());
return fresh.map((it) => ({
  json: { login: it.user.login, starred_at: it.starred_at }
}));

// Merge the enriched GitHub profile with the AI pitch into a Slack payload.
// name / company / bio are user-controlled, so escape before putting them in mrkdwn.
function esc(v) {
  return String(v == null ? '' : v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/([*_~`|])/g, '\u200b$1');
}

const user = $('Enrich: Get User Profile').item.json;
const ai = $json || {};
const pitchRaw = (ai.message && ai.message.content) || ai.text || ai.content ||
  (ai.choices && ai.choices[0] && ai.choices[0].message && ai.choices[0].message.content) || '';
const pitch = esc(String(pitchRaw).trim()) || '(pitch unavailable)';
const cfg = $('Load Sync State').first().json;
const header = ':dart: New high-value lead starred ' + cfg.repoOwner + '/' + cfg.repoName;
console.log('[lead-sniper] qualified lead ' + (user.login) + ' followers=' + user.followers +
  ' public_repos=' + user.public_repos + ' -> posting to Slack');

return {
  json: {
    text: header,
    blocks: [
      { type: 'section', text: { type: 'mrkdwn', text: '*' + header + '*' } },
      { type: 'section', fields: [
        { type: 'mrkdwn', text: '*Name:*\n' + esc(user.name || user.login) },
        { type: 'mrkdwn', text: '*Company:*\n' + esc(user.company || '-') },
        { type: 'mrkdwn', text: '*Followers:*\n' + user.followers },
        { type: 'mrkdwn', text: '*Public repos:*\n' + user.public_repos }
      ] },
      { type: 'section', text: { type: 'mrkdwn', text: '*Bio:*\n' + esc(user.bio || '-') } },
      { type: 'section', text: { type: 'mrkdwn', text: '*AI sales pitch:*\n' + pitch } },
      { type: 'context', elements: [ { type: 'mrkdwn', text: '<https://github.com/' + encodeURIComponent(user.login) + '|github.com/' + esc(user.login) + '>' } ] }
    ]
  }
};
